  "ACTIVE SIGNALS": "ಸಕ್ರಿಯ ಸಿಗ್ನಲ್‌ಗಳು",
  "Could not load forecast data. Check you are signed in and the backend is running.": "ಮುನ್ಸೂಚನೆ ಡೇಟಾವನ್ನು ಲೋಡ್ ಮಾಡಲು ಸಾಧ್ಯವಾಗಲಿಲ್ಲ. ಲಾಗಿನ್ ಆಗಿರುವುದನ್ನು ಪರಿಶೀಲಿಸಿ.",
  "Press Start to run YOLO on the preloaded video": "ವೀಡಿಯೊದಲ್ಲಿ YOLO ಚಲಾಯಿಸಲು Start ಒತ್ತಿರಿ",
  "Waiting for detections…": "ಪತ್ತೆಹಚ್ಚುವಿಕೆಗಾಗಿ ಕಾಯಲಾಗುತ್ತಿದೆ…",
  "YOLO is scanning. Flagged incidents will appear here.": "YOLO ಸ್ಕ್ಯಾನ್ ಮಾಡುತ್ತಿದೆ. ಗುರುತಿಸಲಾದ ಘಟನೆಗಳು ಇಲ್ಲಿ ಕಾಣಿಸಿಕೊಳ್ಳುತ್ತವೆ.",
  "Could not load ring detection results. Clearance L2+ required.": "ರಿಂಗ್ ಪತ್ತೆ ಫಲಿತಾಂಶಗಳನ್ನು ಲೋಡ್ ಮಾಡಲು ಸಾಧ್ಯವಾಗಲಿಲ್ಲ. L2+ ಕ್ಲಿಯರೆನ್ಸ್ ಅಗತ್ಯವಿದೆ.",
  "No co-accused groups (≥3 shared cases) detected for the current filter.": "ಪ್ರಸ್ತುತ ಫಿಲ್ಟರ್‌ಗೆ ಯಾವುದೇ ಸಹ-ಆರೋಪಿ ಗುಂಪುಗಳು (≥3 ಹಂಚಿಕೆಯ ಪ್ರಕರಣಗಳು) ಪತ್ತೆಯಾಗಿಲ್ಲ.",
  "— groups of co-accused appearing together across multiple FIRs": "— ಬಹು ಎಫ್‌ಐಆರ್‌ಗಳಲ್ಲಿ ಒಟ್ಟಿಗೆ ಕಾಣಿಸಿಕೊಳ್ಳುವ ಸಹ-ಆರೋಪಿಗಳ ಗುಂಪುಗಳು",
  "Session expired — sign in again to see provider status.": "ಸೆಷನ್ ಮುಕ್ತಾಯಗೊಂಡಿದೆ — ಸ್ಥಿತಿಯನ್ನು ನೋಡಲು ಮತ್ತೆ ಸೈನ್ ಇನ್ ಮಾಡಿ.",
  "Couldn't load provider status. Is the backend running?": "ಪ್ರೊವೈಡರ್ ಸ್ಥಿತಿಯನ್ನು ಲೋಡ್ ಮಾಡಲು ಸಾಧ್ಯವಾಗಲಿಲ್ಲ. ಬ್ಯಾಕೆಂಡ್ ಚಾಲನೆಯಲ್ಲಿದೆಯೇ?",
  "Models": "AI ಮಾದರಿಗಳು",
  "Choose the model that powers chat. Keys are set on the server (.env).": "ಚಾಟ್‌ಗೆ ಶಕ್ತಿ ನೀಡುವ ಮಾದರಿಯನ್ನು ಆರಿಸಿ. ಕೀಗಳನ್ನು ಸರ್ವರ್‌ನಲ್ಲಿ ಹೊಂದಿಸಲಾಗಿದೆ.",
  "Deeper reasoning is much slower · cannot be turned off": "ಆಳವಾದ ತರ್ಕವು ನಿಧಾನವಾಗಿರುತ್ತದೆ · ಆಫ್ ಮಾಡಲು ಸಾಧ್ಯವಿಲ್ಲ",
  "Powers the AI Scene Generator on the Board screen": "ಬೋರ್ಡ್ ಸ್ಕ್ರೀನ್‌ನಲ್ಲಿ AI ದೃಶ್ಯ ರಚನೆಕಾರರಿಗೆ ಶಕ್ತಿ ನೀಡುತ್ತದೆ",
  "Protect your account": "ನಿಮ್ಮ ಖಾತೆಯನ್ನು ರಕ್ಷಿಸಿ",
  "Last sign-in: today, 09:42 from Bengaluru (Chrome · Windows)": "ಕೊನೆಯ ಲಾಗಿನ್: ಇಂದು, 09:42 ಬೆಂಗಳೂರಿನಿಂದ (Chrome · Windows)",
