  "Display a glowing dot that follows your index finger.": "ನಿಮ್ಮ ತೋರುಬೆರಳನ್ನು ಅನುಸರಿಸುವ ಪ್ರಕಾಶಮಾನವಾದ ಚುಕ್ಕೆಯನ್ನು ಪ್ರದರ್ಶಿಸುತ್ತದೆ.",
  "Say “Satyam” to open the voice copilot without touching the mic.": "ಮೈಕ್ ಮುಟ್ಟದೆ ಧ್ವನಿ ಸಹಾಯಕವನ್ನು ತೆರೆಯಲು “Satyam” ಎಂದು ಹೇಳಿ.",
