    "ಕನ್ನಡ ಅಥವಾ ಇಂಗ್ಲಿಷ್‌ನಲ್ಲಿ ಕೇಳಿ. ಸತ್ಯಂ ಪ್ರಕರಣದ ನಿರೂಪಣೆಗಳ ಮೇಲೆ ಗ್ರೌಂಡೆಡ್ ಟೆಕ್ಸ್ಟ್-ಟು-SQL ಮತ್ತು RAG ಅನ್ನು ನಡೆಸುತ್ತದೆ, ಪ್ರತಿ ಮೂಲವನ್ನು ಉಲ್ಲೇಖಿಸುತ್ತದೆ ಮತ್ತು ನಿಮಗೆ ಮಾತನಾಡುವ ಸಾರಾಂಶವನ್ನು ಹಿಂತಿರುಗಿಸುತ್ತದೆ.",
