const LLM_CACHE_KEY = "satyam.translation.llm-cache";

/** Load any LLM-generated translations cached in localStorage and merge them
 *  into the runtime dict. Called once on provider mount. */
function loadLLMCache(): Record<string, string> {
  if (typeof window === "undefined") return {};
  try {
    const raw = localStorage.getItem(LLM_CACHE_KEY);
    if (raw) return JSON.parse(raw) as Record<string, string>;
  } catch {}
  return {};
}

/** Call the backend /settings/translate endpoint which uses Groq Llama-3.1-70B
 *  to translate all DICT keys that currently fall back to English.
 *
 *  Strategy: we use a tracking proxy — render a fake KN pass over every known
 *  DICT key AND collect any string seen by t() that had no translation.
 *  All untranslated strings (returned as-is) are sent to Groq in batches.
 */
export async function enrichDictWithLLM(
  onProgress?: (msg: string, count: number, total: number) => void,
): Promise<number> {
  const { API_BASE, getAuthToken } = await import("@/lib/api/client");
  const token = getAuthToken() ?? "";

  // Collect strings that have NO Kannada translation:
  // 1. Every key in DICT that maps to itself (shouldn't happen, but covers edge cases)
  // 2. Strings collected via the runtime miss tracker (populated during normal use)
  const missedKey = "satyam.translation.misses";
  let runtimeMisses: string[] = [];
  try {
    const raw = localStorage.getItem(missedKey);
    if (raw) runtimeMisses = JSON.parse(raw) as string[];
  } catch {}

  // Combine: static manifest + runtime misses — everything needing translation
  // Filter to only strings not already in DICT with a real Kannada value
  const selfHits = Object.keys(DICT).filter((k) => DICT[k] === k);
  const allMissing = Array.from(
    new Set([...ALL_TRANSLATABLE, ...selfHits, ...runtimeMisses]),
  ).filter((s) => {
    if (!s || s.trim().length <= 1) return false;
    // Skip if already in DICT with a real Kannada translation
    const existing = DICT[s];
    if (existing && existing !== s && /[\u0C80-\u0CFF]/.test(existing)) return false;
    // Skip pure numbers / symbols
    if (/^[\d\s.%,:/()[\]{}#@!?]+$/.test(s)) return false;
    // Skip strings already in Kannada
    if (/[\u0C80-\u0CFF]/.test(s)) return false;
    return true;
  });

  if (allMissing.length === 0) {
    onProgress?.(
      `All ${ALL_TRANSLATABLE.length} strings are already translated — nothing to enrich.`,
      0,
      0,
    );
    try {
      localStorage.removeItem(missedKey);
    } catch {}
    return 0;
  }

  const total = ALL_TRANSLATABLE.length + selfHits.length + runtimeMisses.length;
  onProgress?.(`Translating ${allMissing.length} UI strings…`, 0, allMissing.length);

  const BATCH = 20;
  const allNew: Record<string, string> = {};
  let added = 0;

  for (let i = 0; i < allMissing.length; i += BATCH) {
    const batch = allMissing.slice(i, i + BATCH);
    onProgress?.(
      `UI strings: batch ${Math.floor(i / BATCH) + 1}/${Math.ceil(allMissing.length / BATCH)} · ${added} done`,
      added,
      allMissing.length,
    );

    try {
      const res = await fetch(`${API_BASE}/settings/db-source/translate`, {
        method: "POST",
        headers: {
          "content-type": "application/json",
          ...(token ? { authorization: `Bearer ${token}` } : {}),
        },
        body: JSON.stringify({ strings: batch }),
      });

      if (!res.ok) {
        const detail = await res.text();
        throw new Error(`Backend returned ${res.status}: ${detail}`);
      }

      const data: { translations: Record<string, string> } = await res.json();
      let batchAdded = 0;
      for (const [k, v] of Object.entries(data.translations)) {
        if (v && v !== k && /[\u0C80-\u0CFF]/.test(v)) {
          // Valid Kannada translation — apply immediately to live DICT
          DICT[k] = v;
          allNew[k] = v;
          added++;
          batchAdded++;
        }
      }
      if (batchAdded > 0 && typeof window !== "undefined") {
        window.dispatchEvent(new CustomEvent("satyam-translations-updated"));
      }
    } catch (err) {
      console.warn("[i18n] enrichDictWithLLM batch failed:", err);
      // Continue with remaining batches — partial enrichment is still useful
    }
  }

  // Persist to localStorage so subsequent page loads use these translations
  try {
    const existing = loadLLMCache();
    localStorage.setItem(LLM_CACHE_KEY, JSON.stringify({ ...existing, ...allNew }));
    // Clear miss tracker — everything has been processed
    localStorage.removeItem(missedKey);
    if (typeof window !== "undefined") {
      window.dispatchEvent(new CustomEvent("satyam-translations-updated"));
    }
  } catch {}

  onProgress?.(`UI strings done — ${added} translated.`, added, allMissing.length);
  return added;
}

/** Translate synthetic dataset values (station names, districts, crime types, statuses)
 *  via Groq Llama-3.1-70B and cache them in localStorage for tData() to use.
 */
export async function enrichDataWithLLM(
  onProgress?: (msg: string, count: number, total: number) => void,
): Promise<number> {
  const { API_BASE, getAuthToken } = await import("@/lib/api/client");
  const token = getAuthToken() ?? "";

  // Fetch unique data values from the DB
  onProgress?.("Fetching unique data values from database…", 0, 1);
  let dataValues: {
    station_names: string[];
    districts: string[];
    crime_types: string[];
    statuses: string[];
  };
  try {
    const r = await fetch(`${API_BASE}/settings/db-source/data-values`, {
      headers: { ...(token ? { authorization: `Bearer ${token}` } : {}) },
    });
    if (!r.ok) throw new Error(`${r.status}`);
    dataValues = await r.json();
  } catch (err) {
    onProgress?.(`Could not fetch data values: ${err}. Skipping data translation.`, 0, 0);
    return 0;
  }

  // Import setDataTranslations at runtime to avoid circular dependency
  const { setDataTranslations } = await import("@/lib/tData");

  const SYSTEM = `You are translating Karnataka State Police database values to formal Kannada (ಕನ್ನಡ).
Rules:
1. Keep "PS", "Police Station" abbreviations in English within names
2. Keep district names in Kannada script (they are Karnataka place names)
3. Station names: translate descriptive parts to Kannada, keep "PS" suffix
4. Return ONLY valid JSON {"english": "ಕನ್ನಡ", ...}
5. No markdown, no explanation`;

  const BATCH = 20;
  let total = 0;

  // Translate each field type
  const fieldGroups: [string, string[], string][] = [
    [
      "station",
      dataValues.station_names,
      "Translate these Karnataka police station names to Kannada. Keep 'PS' suffix in English.",
    ],
    [
      "district",
      dataValues.districts,
      "Translate these Karnataka district names to Kannada script.",
    ],
    [
      "crime_type",
      dataValues.crime_types,
      "Translate these crime type names to Kannada. Use official police terminology.",
    ],
    ["status", dataValues.statuses, "Translate these case status values to Kannada."],
  ];

  for (const [field, values, hint] of fieldGroups) {
    if (!values.length) continue;
    const fieldTotal = values.length;
    onProgress?.(`Translating ${fieldTotal} ${field} values…`, total, total + fieldTotal);

    for (let i = 0; i < values.length; i += BATCH) {
      const batch = values.slice(i, i + BATCH);
      onProgress?.(
        `${field}: batch ${Math.floor(i / BATCH) + 1}/${Math.ceil(values.length / BATCH)} · ${total} done`,
        total,
        total + fieldTotal,
      );

      try {
        const r = await fetch(`${API_BASE}/settings/db-source/translate`, {
          method: "POST",
          headers: {
            "content-type": "application/json",
            ...(token ? { authorization: `Bearer ${token}` } : {}),
          },
          body: JSON.stringify({
            strings: batch,
            system_hint: hint,
          }),
        });
        if (!r.ok) continue;
        const data: { translations: Record<string, string> } = await r.json();
        const valid: Record<string, string> = {};
        for (const [k, v] of Object.entries(data.translations)) {
          if (v && v !== k && v.trim()) {
            valid[k] = v;
            total++;
          }
        }
        if (Object.keys(valid).length > 0) {
          setDataTranslations(field, valid);
        }
      } catch {
        /* continue with next batch */
      }
    }
  }

  onProgress?.(`Data values done — ${total} translated.`, total, total);
  return total;
}

/** Track strings that t() returned unchanged (no translation found). */
function trackMiss(s: string): void {
  if (typeof window === "undefined" || !s || s.length <= 1) return;
  // Skip strings that look like they shouldn't be translated
  if (/^[\d\s.%,:/()[\]{}#@!?]+$/.test(s)) return;
  if (/[\u0C80-\u0CFF]/.test(s)) return; // already Kannada
  try {
    const key = "satyam.translation.misses";
    const existing: string[] = JSON.parse(localStorage.getItem(key) ?? "[]");
    if (!existing.includes(s)) {
      existing.push(s);
      // Cap at 500 to avoid storage bloat
      localStorage.setItem(key, JSON.stringify(existing.slice(-500)));
    }
  } catch {}
}


export function translateDynamicPatterns(s: string): string | null {
  if (!s || typeof s !== "string") return null;

  // 1. "Activity up X% vs prior Y-day period (A incidents vs B baseline). C total incidents recorded."
  let m = s.match(/^Activity up (\d+)% vs prior (\d+)-day period \((\d+) incidents? vs (\d+) baseline\)\.\s*(\d+) total incidents recorded\.?$/i);
  if (m) {
    return `ಹಿಂದಿನ ${m[2]}-ದಿನಗಳ ಅವಧಿಗೆ ಹೋಲಿಸಿದರೆ ಚಟುವಟಿಕೆ ${m[1]}% ಹೆಚ್ಚಾಗಿದೆ (${m[4]} ಬೇಸ್‌ಲೈನ್ ವಿರುದ್ಧ ${m[3]} ಘಟನೆಗಳು). ಒಟ್ಟು ${m[5]} ಘಟನೆಗಳು ದಾಖಲಾಗಿವೆ.`;
  }

  // 2. "Activity up X% vs prior Y-day period (A incidents vs B baseline)"
  m = s.match(/^Activity up (\d+)% vs prior (\d+)-day period \((\d+) incidents? vs (\d+) baseline\)\.?$/i);
  if (m) {
    return `ಹಿಂದಿನ ${m[2]}-ದಿನಗಳ ಅವಧಿಗೆ ಹೋಲಿಸಿದರೆ ಚಟುವಟಿಕೆ ${m[1]}% ಹೆಚ್ಚಾಗಿದೆ (${m[4]} ಬೇಸ್‌ಲೈನ್ ವಿರುದ್ಧ ${m[3]} ಘಟನೆಗಳು).`;
  }

  // 3. "Activity up X% vs prior Y-day period"
  m = s.match(/^Activity up (\d+)% vs prior (\d+)-day period\.?$/i);
  if (m) {
    return `ಹಿಂದಿನ ${m[2]}-ದಿನಗಳ ಅವಧಿಗೆ ಹೋಲಿಸಿದರೆ ಚಟುವಟಿಕೆ ${m[1]}% ಹೆಚ್ಚಾಗಿದೆ.`;
  }

  // 4. "X incidents in the latest data window. No comparable prior-period data - treat as emerging pattern. Y total incidents on record."
  m = s.match(/^(\d+) incidents? in the latest data window\.\s*No comparable prior-period data - treat as emerging pattern\.\s*(\d+) total incidents on record\.?$/i);
  if (m) {
    return `ಇತ್ತೀಚಿನ ಡೇಟಾ ಅವಧಿಯಲ್ಲಿ ${m[1]} ಘಟನೆಗಳು ದಾಖಲಾಗಿವೆ. ಹಿಂದಿನ ಅವಧಿಯ ಹೋಲಿಸಬಹುದಾದ ಡೇಟಾ ಲಭ್ಯವಿಲ್ಲ - ಹೊಸ ಮಾದರಿಯಾಗಿ ಪರಿಗಣಿಸಿ. ದಾಖಲೆಯಲ್ಲಿ ಒಟ್ಟು ${m[2]} ಘಟನೆಗಳು.`;
  }

  // 5. "X incidents in the latest data window. No comparable prior-period data - treat as emerging pattern."
  m = s.match(/^(\d+) incidents? in the latest data window\.\s*No comparable prior-period data - treat as emerging pattern\.?$/i);
  if (m) {
    return `ಇತ್ತೀಚಿನ ಡೇಟಾ ಅವಧಿಯಲ್ಲಿ ${m[1]} ಘಟನೆಗಳು ದಾಖಲಾಗಿವೆ. ಹಿಂದಿನ ಅವಧಿಯ ಹೋಲಿಸಬಹುದಾದ ಡೇಟಾ ಲಭ್ಯವಿಲ್ಲ - ಹೊಸ ಮಾದರಿಯಾಗಿ ಪರಿಗಣಿಸಿ.`;
  }

  // 6. "Increase patrols in {district} targeting {crime_type} during {start} - {end}."
  m = s.match(/^Increase patrols in (.+?) targeting (.+?) during (\d\d?:\d\d)\s*-\s*(\d\d?:\d\d)\.?$/i);
  if (m) {
    const rawDist = m[1].trim();
    const rawCrime = m[2].trim();
    const distKn = DICT[rawDist] ?? rawDist;
    const crimeKn = DICT[rawCrime] ?? rawCrime;
    return `${m[3]} - ${m[4]} ಸಮಯದಲ್ಲಿ ${distKn} ನಲ್ಲಿ ${crimeKn} ನಿಯಂತ್ರಣಕ್ಕಾಗಿ ಗಸ್ತು ಹೆಚ್ಚಿಸಿ.`;
  }

  // 7. Backtest Explanation
  m = s.match(/^Across (\d+) rolling (\d+)-day windows, the top decile of scored cells \((\d+) of (\d+) cells, ([\d\.]+)% of the study area\) contained (\d+) of (\d+) held-out incidents — a ([\d\.]+)% hit rate \(95% CI ([\d\-]+)%\)\. That is PAI ([\d\.]+)x versus random targeting of the same area, and PEI ([\d\.]+) of the best any selection of (\d+) cells could have achieved with hindsight\.?$/i);
  if (m) {
    return `${m[1]} ರೋಲಿಂಗ್ ${m[2]}-ದಿನಗಳ ಅವಧಿಗಳಲ್ಲಿ, ಅಗ್ರ ದಶಕದ ಸ್ಕೋರ್ ಮಾಡಿದ ಕೋಶಗಳು (${m[4]} ಕೋಶಗಳಲ್ಲಿ ${m[3]}, ಅಧ್ಯಯನ ಪ್ರದೇಶದ ${m[5]}%) ${m[7]} ಪರೀಕ್ಷಾರ್ಥ ಘಟನೆಗಳಲ್ಲಿ ${m[6]} ಘಟನೆಗಳನ್ನು ಒಳಗೊಂಡಿವೆ — ${m[8]}% ಹಿಟ್ ದರ (95% CI ${m[9]}%). ಇದು ಅದೇ ಪ್ರದೇಶದ ಯಾದೃಚ್ಛಿಕ ಗುರಿಗಿಂತ ${m[10]}x PAI ಮತ್ತು ಹಿನ್ನೋಟದಲ್ಲಿ ಯಾವುದೇ ${m[12]} ಕೋಶಗಳ ಆಯ್ಕೆಯು ಸಾಧಿಸಬಹುದಾದ ಗರಿಷ್ಠ ಫಲಿತಾಂಶದ ${m[11]} PEI ಆಗಿದೆ.`;
  }

  // 8. Backtest Caveat 2
  m = s.match(/^Cells with no incident history before a fold's origin are never selected, but their held-out incidents stay in the denominator \((\d+) of (\d+) incidents, (\d+)%\)\.?$/i);
  if (m) {
    return `ಫೋಲ್ಡ್‌ನ ಮೂಲಕ್ಕಿಂತ ಮೊದಲು ಯಾವುದೇ ಘಟನೆಯ ಇತಿಹಾಸವಿಲ್ಲದ ಕೋಶಗಳನ್ನು ಎಂದಿಗೂ ಆಯ್ಕೆ ಮಾಡಲಾಗುವುದಿಲ್ಲ, ಆದರೆ ಅವುಗಳ ಘಟನೆಗಳು ಛೇದದಲ್ಲಿ ಉಳಿಯುತ್ತವೆ (${m[2]} ಘಟನೆಗಳಲ್ಲಿ ${m[1]}, ${m[3]}%).`;
  }

  return null;
}

export function I18nProvider({ children }: { children: ReactNode }) {
  const [lang, setLangState] = useState<Lang>("EN");
  const [tick, setTick] = useState(0);

  useEffect(() => {
    try {
      const saved = localStorage.getItem("fq-lang") as Lang | null;
      if (saved === "EN" || saved === "KN") setLangState(saved);
    } catch {}

    // Merge any previously-enriched LLM translations into the live DICT
    const cached = loadLLMCache();
    for (const [k, v] of Object.entries(cached)) {
      if (v && v !== k) DICT[k] = v;
    }
  }, []);

  useEffect(() => {
    if (typeof window === "undefined") return;
    const handleUpdate = () => {
      setTick((t) => t + 1);
    };
    window.addEventListener("satyam-translations-updated", handleUpdate);
    return () => window.removeEventListener("satyam-translations-updated", handleUpdate);
  }, []);

  const setLang = (l: Lang) => {
    setLangState(l);
    try {
      localStorage.setItem("fq-lang", l);
    } catch {}
    if (typeof document !== "undefined") {
      document.documentElement.lang = l === "KN" ? "kn" : "en";
    }

    // Auto-trigger background enrichment on first switch to Kannada
    if (l === "KN") {
      try {
        const enriched = localStorage.getItem("satyam.translation.enriched");
        if (enriched !== "1") {
          console.log("[i18n] Auto-triggering Kannada enrichment...");
          enrichDictWithLLM()
            .then(() => enrichDataWithLLM())
            .then(() => {
              localStorage.setItem("satyam.translation.enriched", "1");
            })
            .catch((err) => {
              console.error("[i18n] Auto-enrichment failed:", err);
            });
        }
      } catch (err) {
        console.error("[i18n] Could not read/write local storage for auto-enrichment:", err);
      }
    }
  };

  const t = (s: string) => {
    if (lang !== "KN" || !s || typeof s !== "string") return s;
    const translation = DICT[s];
    if (translation !== undefined) return translation;
    const dynamicTranslation = translateDynamicPatterns(s);
    if (dynamicTranslation !== null) return dynamicTranslation;
    // Track this as a miss so enrichDictWithLLM can find and translate it later
    trackMiss(s);
    return s;
  };

  return <I18nCtx.Provider value={{ lang, setLang, t }}>{children}</I18nCtx.Provider>;
}

export const useI18n = () => useContext(I18nCtx);
export const useT = () => useContext(I18nCtx).t;
